<template><div class="page"><div class="section-title"><div><h2>故障排查</h2><span class="muted">{{incident?.alert_name}} · {{incident?.status}}</span></div><n-button @click="resolve">标记已解决</n-button></div><div class="panel"><n-descriptions bordered :column="2"><n-descriptions-item label="告警">{{incident?.alert_name}}</n-descriptions-item><n-descriptions-item label="Fingerprint">{{incident?.alert_fingerprint}}</n-descriptions-item><n-descriptions-item label="上下文" :span="2"><pre>{{JSON.stringify(incident?.context||{},null,2)}}</pre></n-descriptions-item></n-descriptions></div><section class="panel chat-main" style="height:55vh"><div class="messages"><div v-for="(m,i) in messages" :key="i" :class="['message',m.role]">{{m.content}}</div></div><div class="chat-input"><n-input v-model:value="input" placeholder="询问 Agent 如何排查该故障..." @keydown.enter.exact.prevent="send"/><n-button type="primary" :loading="streaming" @click="send">发送</n-button></div></section></div></template>
<script setup>import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {incidentApi,request,streamConversation} from '@/api';const route=useRoute(),incident=ref(null),messages=ref([]),input=ref(''),streaming=ref(false);async function load(){incident.value=await incidentApi.get(route.params.id);const r=await request.get(`/incidents/${route.params.id}/messages`);messages.value=(r.messages||[]).map(x=>({role:x.role,content:x.content}))}async function send(){const q=input.value.trim();if(!q||streaming.value)return;input.value='';messages.value.push({role:'user',content:q},{role:'assistant',content:''});streaming.value=true;try{await streamConversation(`/incidents/${route.params.id}/chatStream`,q,t=>messages.value.at(-1).content+=t)}finally{streaming.value=false}}async function resolve(){await request.post(`/incidents/${route.params.id}/resolve`);await load()}onMounted(load)</script>
